from .exceptions import OperationFailed


class Response:

    def __init__(self, response, ignore_failure=False):
        self.response = response
        self.ignore_failure = ignore_failure

    @property
    def verify(self):
        if not self.ignore_failure and any(True for item in self.response if not item['success']):
            exc_msg = f'The operation failed for at least one alarm:\n{self.response}'
            raise OperationFailed(exc_msg)
        return self.response
